    lanternPivot.rotation.z = S.swing + Math.sin(S.t * 1.1) * 0.03;
    lanternPivot.rotation.x = Math.sin(S.t * 0.83) * 0.03;
    // atmosphere
    const A = atmo(y), dark = S.dark, keepLight = 1 - dark * 0.88;
